// COMPACT RESULTS – returns short job summaries only (no long CV / cover letter text),
// so the chat agent stays within Groq's free token-per-minute limit.
// v2: hides skipped/rejected jobs unless the agent asked for that status,
//     and re-checks red flags at read time (catches rows scored before the flag rules existed).
const input = $("When Called by Agent").first().json;
const askedStatus = String(input.status || "").trim().toLowerCase();
const limit = Math.min(Math.max(Number(input.limit) || 5, 1), 10);

const HIDDEN = ["skipped", "rejected"];
const RED_FLAG_TITLE = /\b(trainee|traineeship|no experience (needed|required)|course|bootcamp|funded training|career change programme)\b/i;

let rows = $input.all().map((i) => i.json).filter((r) => r.job_id);
// Keyword search across title AND company (e.g. "Searchability" or "data").
const words = String(input.title_words || "").toLowerCase().split(/\s+/).filter(Boolean);
if (words.length) rows = rows.filter((r) => { const hay = (String(r.title || "") + " " + String(r.company || "")).toLowerCase(); return words.every((w) => hay.includes(w)); });
const hiddenCount = askedStatus ? 0 : rows.filter((r) => HIDDEN.includes(String(r.status || "").toLowerCase())).length;
if (!askedStatus) rows = rows.filter((r) => !HIDDEN.includes(String(r.status || "").toLowerCase()));

rows = rows.map((r) => {
  let flags = String(r.flags || "").trim();
  let fit = r.fit;
  if (RED_FLAG_TITLE.test(String(r.title || "")) && !/paid training|training scheme/i.test(flags)) {
    flags = (flags && flags !== "-" ? flags + "; " : "") + "RED FLAG: possible paid training scheme – check before applying";
  }
  if (/red flag/i.test(flags)) fit = "Red flag";
  return { ...r, flags, fit };
});

// Red-flag jobs go to the bottom; everything else stays in score order.
rows.sort((a, b) => (a.fit === "Red flag") - (b.fit === "Red flag") || (Number(b.match_score) || 0) - (Number(a.match_score) || 0));

return [{ json: {
  count: rows.length,
  hidden_skipped_or_rejected: hiddenCount,
  jobs: rows.slice(0, limit).map((r) => ({
    job_id: r.job_id, title: r.title, company: r.company, location: r.location, salary: r.salary,
    match_score: r.match_score, fit: r.fit, flags: r.flags || "-", status: r.status, url: r.url,
    has_tailored_cv: Boolean(r.tailored_cv)
  }))
} }];
